	testcases := []struct {
		name string
		in   *ConversionCustomContainer
	}{
		{
			name: "nil",
			in:   &ConversionCustomContainer{},
		},
		{
			name: "empty",
			in: &ConversionCustomContainer{
				Slice:   []ConversionCustom{},
