			if err := Convert_example_ConversionCustomContainer_To_v1_ConversionCustomContainer(out, roundtrip, nil); err != nil {
				t.Fatal(err)
			}

			if !reflect.DeepEqual(original, roundtrip) {
				t.Fatalf("expected:\n%#v\ngot:\n%#v", original, roundtrip)
			}
		})
	}
}

